<template><section class="sharing-panel"><h3>{{ __('External collaboration') }}</h3><p class="text-muted">{{ __('Share this task’s title, status, dates and a separate discussion. Internal descriptions, comments, attachments and assignees stay private.') }}</p><button class="btn-ghost" @click="load" :disabled="busy">{{ data ? __('Refresh access') : __('Manage external access') }}</button><p v-if="error" role="alert">{{ error }}</p><template v-if="data"><ul><li v-for="share in data.shares" :key="share.user">{{ share.user }} <button class="btn-ghost" :disabled="busy" @click="revoke(share.user)">{{ __('Revoke') }}</button></li></ul><form @submit.prevent="share"><label>{{ __('Existing external user') }}<select v-model="user" class="field" required><option value="">{{ __('Choose a website user') }}</option><option v-for="candidate in data.candidates" :key="candidate.name" :value="candidate.name">{{ candidate.full_name }} · {{ candidate.name }}</option></select></label><button class="btn-primary" :disabled="busy||!user">{{ __('Share task') }}</button></form><p v-if="notice" role="status">{{ notice }}</p><a href="/pulse/external" target="_blank" rel="noopener">{{ __('Open shared work portal') }}</a><h4>{{ __('Shared discussion') }}</h4><ul><li v-for="item in discussion" :key="item.name"><p>{{ item.content }}</p><small>{{ item.creation }}</small></li></ul><form @submit.prevent="reply"><label>{{ __('Reply visible to external participants') }}<textarea v-model="content" class="field" required maxlength="5000" /></label><button class="btn-ghost" :disabled="busy||!content.trim()">{{ __('Post reply') }}</button></form></template></section></template>
<script setup>
import {ref} from 'vue'
import {call} from 'frappe-ui'
import { __ } from '@/translation'
const props=defineProps({task:{type:String,required:true}})
const data=ref(null),discussion=ref([]),user=ref(''),content=ref(''),busy=ref(false),error=ref(''),notice=ref('')
function failure(e){error.value=e.messages?.join(' ')||__('Unable to update external access. Check your sharing permission.')}
async function load(){error.value='';try{const [shares,comments]=await Promise.all([call('pulse.api.external.sharing',{task:props.task}),call('pulse.api.external.discussion',{task:props.task})]);data.value=shares;discussion.value=comments}catch(e){failure(e)}}
async function action(method,values){busy.value=true;error.value='';try{await call('pulse.api.external.'+method,{task:props.task,...values});await load();return true}catch(e){failure(e);return false}finally{busy.value=false}}
async function share(){if(await action('share',{user:user.value})){notice.value=__('Task shared. Ask the participant to sign in at {0}.',['/pulse/external']);user.value=''}}
async function revoke(user){if(await action('revoke',{user}))notice.value=__('Access revoked.')}
async function reply(){if(await action('reply',{content:content.value}))content.value=''}
</script>
<style scoped>.sharing-panel{padding:16px 0}.sharing-panel h3,.sharing-panel h4{font-size:14px;font-weight:600}.sharing-panel p{font-size:13px;margin:8px 0;white-space:pre-wrap}.sharing-panel li{padding:8px 0;border-bottom:1px solid var(--border-color,#e6e8ec)}.sharing-panel form{display:grid;gap:10px;margin:12px 0}.sharing-panel label{display:grid;gap:6px}.sharing-panel button{justify-self:start}.sharing-panel h4{margin-top:24px}</style>
